(62779, 50, 0, 'This canyon will make for excellent hunting!', 14, 0, 0, 0, 0, 0, 0, 0, 'Pathun Duskhide - Windhorn Canyon - Pathun Duskhide - Aggro Line'),
(62779, 51, 0, 'You shall be crushed!', 14, 0, 0, 0, 0, 0, 0, 0, 'Pathun Duskhide - Windhorn Canyon - Pathun Duskhide - 50% Health Line'),
(62779, 52, 0, 'I travel to the great beyond...', 14, 0, 0, 0, 0, 0, 0, 0, 'Pathun Duskhide - Windhorn Canyon - Pathun Duskhide - Death Line'),
(62781, 50, 0, 'Our destiny has been foretold!', 14, 0, 0, 0, 0, 0, 0, 0, 'Prophet Stormhoof - Windhorn Canyon - Prophet Stormhoof - Aggro Line'),
(62781, 51, 0, 'I have seen the future, and it is your death!', 14, 0, 0, 0, 0, 0, 0, 0, 'Prophet Stormhoof - Windhorn Canyon - Prophet Stormhoof - 50% Health Line'),
(62781, 52, 0, 'My sight, has left me!', 14, 0, 0, 0, 0, 0, 0, 0, 'Prophet Stormhoof - Windhorn Canyon - Prophet Stormhoof - Death Line'),
(62783, 50, 0, 'Behold the howling wind!', 14, 0, 0, 0, 0, 0, 0, 0, 'Ambassador Vortalus - Windhorn Canyon - Ambassador Vortalus - Aggro Line'),
(62783, 51, 0, 'We seek unity...', 14, 0, 0, 0, 0, 0, 0, 0, 'Ambassador Vortalus - Windhorn Canyon - Ambassador Vortalus - 50% Health Line'),
(62783, 52, 0, 'Disperse...', 14, 0, 0, 0, 0, 0, 0, 0, 'Ambassador Vortalus - Windhorn Canyon - Ambassador Vortalus - Death Line'),
(62784, 50, 0, 'Be destroyed by my hands!', 14, 0, 0, 0, 0, 0, 0, 0, 'Walgan Bloodcaller - Windhorn Canyon - Walgan Bloodcaller - Aggro Line'),
(62784, 51, 0, 'Enough!', 14, 0, 0, 0, 0, 0, 0, 0, 'Walgan Bloodcaller - Windhorn Canyon - Walgan Bloodcaller - 50% Health Line'),
(62784, 52, 0, 'This cannot... be...', 14, 0, 0, 0, 0, 0, 0, 0, 'Walgan Bloodcaller - Windhorn Canyon - Walgan Bloodcaller - Death Line');
