INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(41976, 0, 0, 0, 0, 0, 0, 0, 0, 'Magnificent, I was once as ignorant to think the Tauren had no history, and just wandered plains like nomads. This certainly has changed my view upon them as a whole.$B$BYou have done well adventurer, please, take this coin for doing such brave, and noble work.', 0),
(41982, 0, 0, 0, 0, 0, 0, 0, 0, '<Cairne gazes upon you with a look of approval.>$B$BYou have done well, and have brought peace to the Tauren. The Deathtotem shall trouble us no longer young blood. Please, be bestowed by an item that shall bring you fortune in the days to come.', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(41976, 0, 0, 'Remember, the Canyon is located deep within Thousand Needles, you will need to travel to the far corners of Kalimdor to find it.', 0),
(41982, 0, 0, 'Take heart, and be careful in your task. I am certain that the Deathtotem are aided by dark magic. Bring what company you can, and be swift in your actions.', 0);
